const input = $input.first().json;
const body = input.body ?? input;
const context = body.context ?? body.suspect ?? body;
const linkedReportIds = body.linked_report_ids ?? context.linked_report_ids ?? [];
const reports = context.reports ?? body.reports ?? [];
const now = new Date().toISOString();

function asArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value.filter(Boolean) : [value].filter(Boolean);
}

function safeString(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function domainFromEmail(value) {
  const text = safeString(value);
  if (!text.includes('@')) return '';
  return text.split('@').pop().toLowerCase();
}

function quote(value) {
  const text = safeString(value).replace(/["\n\r]/g, ' ').replace(/\s+/g, ' ').trim();
  return text ? `"${text}"` : '';
}

function addQuery(set, value) {
  const text = safeString(value).replace(/\s+/g, ' ').trim();
  if (text.length >= 3 && text.length <= 180) set.add(text);
}

const primaryIdentifier = safeString(context.primary_identifier ?? context.identifier ?? body.primary_identifier);
const identifierType = safeString(context.identifier_type ?? body.identifier_type);
const suspectType = safeString(context.suspect_type ?? body.suspect_type ?? 'unknown');
const claimedName = safeString(context.claimed_name ?? context.display_label);
const claimedRole = safeString(context.claimed_role);
const claimedOrganization = safeString(context.claimed_organization ?? context.organization);
const knownDomains = new Set(asArray(context.known_domains));
const knownRepositories = asArray(context.known_repositories ?? context.repositories);
const knownUrls = asArray(context.known_urls ?? context.urls);
const knownWallets = asArray(context.known_wallets ?? context.wallets);
const knownMarketplaceHandles = asArray(context.known_marketplace_handles ?? context.marketplace_handles);

if (identifierType === 'email' || primaryIdentifier.includes('@')) {
  const domain = domainFromEmail(primaryIdentifier);
  if (domain) knownDomains.add(domain);
}

for (const url of knownUrls) {
  try {
    const parsed = new URL(url.startsWith('http') ? url : `https://${url}`);
    if (parsed.hostname) knownDomains.add(parsed.hostname.replace(/^www\./, ''));
  } catch (error) {}
}

const queries = new Set();
if (primaryIdentifier && !primaryIdentifier.includes('@')) addQuery(queries, quote(primaryIdentifier));
if (claimedName && claimedOrganization) addQuery(queries, `${quote(claimedName)} ${quote(claimedOrganization)}`);
if (claimedOrganization && claimedRole) addQuery(queries, `${quote(claimedOrganization)} ${quote(claimedRole)} recruiter`);

for (const domain of knownDomains) {
  addQuery(queries, `${quote(domain)} scam`);
  addQuery(queries, `${quote(domain)} phishing`);
  if (claimedOrganization) addQuery(queries, `${quote(domain)} ${quote(claimedOrganization)}`);
}

for (const repo of knownRepositories) {
  addQuery(queries, `${quote(repo)} malware`);
  addQuery(queries, `${quote(repo)} npm install security`);
}

for (const wallet of knownWallets) {
  addQuery(queries, quote(wallet));
  addQuery(queries, `${quote(wallet)} scam`);
}

for (const handle of knownMarketplaceHandles) {
  addQuery(queries, `${quote(handle)} scam`);
  addQuery(queries, `${quote(handle)} fake escrow`);
}

for (const report of reports) {
  const summary = safeString(report.desensitized_summary ?? report.redacted_material).toLowerCase();
  if (summary.includes('approved vendor')) addQuery(queries, '"approved vendor" "reimburse after first paycheck"');
  if (summary.includes('off-platform') || summary.includes('off platform')) addQuery(queries, '"off-platform" "equipment purchase" job scam');
  if (summary.includes('equipment purchase')) addQuery(queries, '"equipment purchase" "job scam"');
}

const selectedQueries = [...queries].slice(0, 8);
const HARDCODED_TAVILY_API_KEY = '';
const HARDCODED_ATTIO_API_KEY = '';
const bodyTavilyApiKey = safeString(body.tavily_api_key ?? body.tavilyApiKey);
const bodyAttioApiKey = safeString(body.attio_api_key ?? body.attioApiKey);
const envTavilyApiKey = typeof $env !== 'undefined' ? $env.TAVILY_API_KEY : undefined;
const envAttioApiKey = typeof $env !== 'undefined' ? $env.ATTIO_API_KEY : undefined;
const varTavilyApiKey = typeof $vars !== 'undefined' ? $vars.TAVILY_API_KEY : undefined;
const varAttioApiKey = typeof $vars !== 'undefined' ? $vars.ATTIO_API_KEY : undefined;
const tavilyApiKey = HARDCODED_TAVILY_API_KEY || bodyTavilyApiKey || process.env.TAVILY_API_KEY || envTavilyApiKey || varTavilyApiKey;
const attioApiKey = HARDCODED_ATTIO_API_KEY || bodyAttioApiKey || process.env.ATTIO_API_KEY || envAttioApiKey || varAttioApiKey;
const errors = [];
const tavilyResults = [];

if (!tavilyApiKey) {
  errors.push('Missing Tavily API key. Paste it into HARDCODED_TAVILY_API_KEY, provide body.tavily_api_key, TAVILY_API_KEY env var, or TAVILY_API_KEY n8n variable.');
}

if (!selectedQueries.length) {
  errors.push('No privacy-safe query ingredients were available.');
}

if (tavilyApiKey && selectedQueries.length) {
  for (const query of selectedQueries) {
    try {
      const response = await fetch('https://api.tavily.com/search', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          authorization: `Bearer ${tavilyApiKey}`
        },
        body: JSON.stringify({
          query,
          search_depth: 'basic',
          max_results: 3,
          include_answer: false,
          include_raw_content: false
        })
      });

      if (!response.ok) {
        errors.push(`Tavily failed for ${query}: HTTP ${response.status}`);
        continue;
      }

      const data = await response.json();
      for (const result of data.results ?? []) {
        tavilyResults.push({
          search_query: query,
          title: result.title ?? '',
          url: result.url ?? '',
          excerpt: result.content ?? '',
          score: result.score ?? null
        });
      }
    } catch (error) {
      errors.push(`Tavily failed for ${query}: ${error.message}`);
    }
  }
}

const byUrl = new Map();
for (const result of tavilyResults) {
  if (!result.url || byUrl.has(result.url)) continue;
  byUrl.set(result.url, result);
}

const evidenceItems = [...byUrl.values()].map((source) => ({
  claim: 'Public web source returned for privacy-safe suspect due diligence query.',
  source_title: source.title,
  source_url: source.url,
  excerpt: source.excerpt.slice(0, 500),
  retrieved_at: now,
  search_query: source.search_query,
  linked_suspect_id: context.suspect_id ?? body.suspect_id ?? null,
  linked_report_ids: linkedReportIds,
  confidence: source.score && source.score > 0.7 ? 'medium' : 'low'
}));

const findings = [];
if (!evidenceItems.length) {
  findings.push({
    type: 'no_reliable_result',
    summary: 'No reliable public source was returned from the privacy-safe query set.',
    linked_identifier: primaryIdentifier || null,
    confidence: 'medium'
  });
} else {
  findings.push({
    type: 'needs_human_review',
    summary: 'Public sources were found and should be reviewed before any user-facing conclusion is made.',
    linked_identifier: primaryIdentifier || null,
    confidence: 'medium'
  });
}

if (claimedOrganization && evidenceItems.length && knownDomains.size) {
  findings.push({
    type: 'verification_gap',
    summary: 'The workflow found public web material, but claimed affiliation still requires human verification against official sources.',
    linked_identifier: [...knownDomains][0],
    confidence: 'medium'
  });
}

const status = errors.length && evidenceItems.length ? 'partial' : errors.length ? 'failed' : 'completed';
const summary = status === 'completed'
  ? 'Web due diligence completed with source-backed results queued for review.'
  : status === 'partial'
    ? 'Web due diligence partially completed; review returned evidence and errors.'
    : 'Web due diligence could not complete with the available inputs and configuration.';

const output = {
  agent_name: 'Web Due Diligence Agent',
  status,
  suspect_id: context.suspect_id ?? body.suspect_id ?? null,
  suspect_object: body.suspect_object ?? context.suspect_object ?? null,
  suspect_type: suspectType,
  linked_report_ids: linkedReportIds,
  queries: selectedQueries,
  summary,
  findings,
  evidence_items: evidenceItems,
  risk_indicator_updates: findings.map((finding) => ({
    category: finding.type,
    severity: finding.type === 'no_reliable_result' ? 'low' : 'medium',
    description: finding.summary
  })),
  attio_writeback: {
    update_suspect: {
      web_due_diligence_status: status,
      web_due_diligence_summary: summary,
      last_investigated_at: now
    },
    create_agent_run: {
      agent_name: 'Web Due Diligence Agent',
      status,
      started_at: body.started_at ?? now,
      finished_at: now,
      query_count: selectedQueries.length,
      errors
    },
    create_sources_from_evidence_items: true,
    create_evidence_items: evidenceItems,
    create_risk_indicators: findings
  },
  requires_review: true,
  errors
};

const attioObject = output.suspect_object || 'people';
const attioRecordId = output.suspect_id;
output.attio_writeback_result = { status: 'skipped', reason: 'Missing Attio API key or Attio record id.' };

if (attioApiKey && attioRecordId) {
  const nextRiskLevel = evidenceItems.length ? 'YELLOW' : (context.risk_level || 'YELLOW');
  const nextConfidence = status === 'completed' ? Math.max(Number(context.risk_score ?? 35), evidenceItems.length ? 55 : 35) : Number(context.risk_score ?? 35);
  const findingsText = JSON.stringify({
    agent_name: output.agent_name,
    status: output.status,
    summary: output.summary,
    queries: output.queries,
    findings: output.findings,
    evidence_items: output.evidence_items.slice(0, 6),
    errors: output.errors,
    updated_at: now
  }, null, 2).slice(0, 50000);

  try {
    const response = await fetch(`https://api.attio.com/v2/objects/${encodeURIComponent(attioObject)}/records/${encodeURIComponent(attioRecordId)}`, {
      method: 'PATCH',
      headers: {
        'content-type': 'application/json',
        authorization: `Bearer ${attioApiKey}`
      },
      body: JSON.stringify({
        data: {
          values: {
            agent_findings: findingsText,
            risk_level: nextRiskLevel,
            confidence: nextConfidence
          }
        }
      })
    });

    const responseText = await response.text();
    if (!response.ok) {
      output.attio_writeback_result = {
        status: 'failed',
        object: attioObject,
        record_id: attioRecordId,
        http_status: response.status,
        error: responseText.slice(0, 500)
      };
      output.errors.push(`Attio writeback failed: HTTP ${response.status}`);
      if (output.status === 'completed') output.status = 'partial';
    } else {
      output.attio_writeback_result = {
        status: 'completed',
        object: attioObject,
        record_id: attioRecordId,
        updated_fields: ['agent_findings', 'risk_level', 'confidence']
      };
    }
  } catch (error) {
    output.attio_writeback_result = {
      status: 'failed',
      object: attioObject,
      record_id: attioRecordId,
      error: error.message
    };
    output.errors.push(`Attio writeback failed: ${error.message}`);
    if (output.status === 'completed') output.status = 'partial';
  }
}

return [{ json: output }];
